for(const score of riscMalawiScores)score.wave24=true;
scores.push(...riscMalawiScores);
for(const score of oaklandScores)score.wave25=true;
scores.push(...oaklandScores);
for(const score of prepareScores)score.wave26=true;
scores.push(...prepareScores);
for(const score of feastScores)score.wave27=true;
