for(const score of edacsScores)score.wave29=true;
scores.push(...edacsScores);
scores.push(masSjiaScore,alt70Score,kawasakiCompleteScore,edcDengueScore,pbmstChildScore,anaphylaxisNiaidScore,ispadDkaScore,chandlerScore);
for (const score of novemberScores) {
  score.aliases ||= [];
  score.specialties ||= [score.specialty];
}
scores.push(...novemberScores);
applySpecialtyDiscovery(scores);
applyYaleObservationReview(scores);
applyClinicalKeywords(scores);
applyClinicalTaxonomy(scores);
applyPopulationNavigation(scores);

// Keep the existing Westley warning when other observations remain unknown.
// Read only own data properties; never infer a missing observation or invoke accessors.
const westley=scores.find(score=>score.id==='westley');
const westleyOwnValue=(values,key)=>{
 try{
  if(values===null||typeof values!=='object'||Array.isArray(values))return undefined;
  const descriptor=Object.getOwnPropertyDescriptor(values,key);
  return descriptor&&Object.hasOwn(descriptor,'value')?descriptor.value:undefined;
 }catch{return undefined;}
};
westley.safeValidate=values=>westley.fields.filter(field=>{
 const value=westleyOwnValue(values,field.id);
 return !['number','string'].includes(typeof value)||!field.options.some(option=>String(option.value)===String(value));
}).map(field=>field.id);
westley.assessPartial=values=>[4,'4',5,'5'].includes(westleyOwnValue(values,'cyanosis'))||[5,'5'].includes(westleyOwnValue(values,'mental'))?{level:'high',alert:'Sinal crítico: cianose ou alteração de consciência exige avaliação imediata e suporte de via aérea, independentemente da faixa numérica.'}:null;

// Known NEWS2 contributions keep the strongest established action without a total.
// Own valid observations only; an unknown value is never treated as normal.
const news2=scores.find(score=>score.id==='news2');
const news2OwnValidValue=(values,field)=>{
 try{
  if(values===null||typeof values!=='object'||Array.isArray(values))return undefined;
  const descriptor=Object.getOwnPropertyDescriptor(values,field.id);
  if(!descriptor||!Object.hasOwn(descriptor,'value'))return undefined;
  const value=descriptor.value;
  if(field.type==='select')return ['number','string'].includes(typeof value)&&field.options.some(option=>String(option.value)===String(value))?Number(value):undefined;
  if(!(typeof value==='number'||(typeof value==='string'&&/^\d+(\.\d+)?$/.test(value))))return undefined;
  const number=Number(value);
  return Number.isFinite(number)&&number>=field.min&&number<=field.max&&(field.step!==1||Number.isInteger(number))&&(field.step!==.1||Math.abs(number*10-Math.round(number*10))<=1e-7)?number:undefined;
 }catch{return undefined;}
};
news2.safeValidate=values=>news2.fields.filter(field=>news2OwnValidValue(values,field)===undefined).map(field=>field.id);
news2.assessPartial=values=>{
 const x=Object.fromEntries(news2.fields.map(field=>[field.id,news2OwnValidValue(values,field)]));
 const saturationKnown=x.spo!==undefined&&x.scale!==undefined&&x.oxygen!==undefined;
 // Seven distinct components; scale selects the saturation rule and never adds points.
 const knownPoints=[
  x.rr===undefined?undefined:x.rr<=8?3:x.rr<=11?1:x.rr<=20?0:x.rr<=24?2:3,
  !saturationKnown?undefined:x.scale===1?(x.spo<=91?3:x.spo<=93?2:x.spo<=95?1:0):(x.spo<=83?3:x.spo<=85?2:x.spo<=87?1:x.spo<=92?0:x.oxygen===0?0:x.spo<=94?1:x.spo<=96?2:3),
  x.oxygen,
  x.sbp===undefined?undefined:x.sbp<=90?3:x.sbp<=100?2:x.sbp<=110?1:x.sbp<220?0:3,
  x.hr===undefined?undefined:x.hr<=40?3:x.hr<=50?1:x.hr<=90?0:x.hr<=110?1:x.hr<=130?2:3,
  x.mental,
  x.temp===undefined?undefined:x.temp<=35?3:x.temp<=36?1:x.temp<=38?0:x.temp<=39?1:2
 ].filter(points=>points!==undefined);
 // Nonnegative unknown contributions cannot undo a threshold already supported here.
 const knownSum=knownPoints.reduce((sum,points)=>sum+points,0);
 if(knownSum>=7)return {level:'high',alert:'Avaliação imediata por equipe com competências de cuidados críticos e monitorização contínua.'};
 if(knownSum>=5)return {level:'medium',alert:'Avaliação clínica urgente e observações pelo menos horárias até definição do plano.'};
 return knownPoints.includes(3)?{level:'medium',alert:'Revisão clínica urgente e observações pelo menos horárias, mesmo com total <5.'}:null;
};

export function validate(score,values){
 if(typeof score.safeValidate==='function')return score.safeValidate(values);
 if(values===null||typeof values!=='object'||Array.isArray(values))return score.fields.map(f=>f.id);
 const errors=[];
 for(const f of score.fields){const v=values[f.id];if(v===undefined||v===null||v===''||typeof v==='boolean'){errors.push(f.id);continue;}
 if(score.id==='pim3'&&f.type==='number'&&['sbp','fio2','pao2','be'].includes(f.id)&&f.allowND===true&&v==='ND')continue;
 if(f.type==='select'){if(!['string','number'].includes(typeof v)||!f.options.some(o=>String(o.value)===String(v)))errors.push(f.id);}
 else {const legal=typeof v==='number'||(typeof v==='string'&&/^\d+(\.\d+)?$/.test(v));if(!legal){errors.push(f.id);continue;}const x=Number(v);if(!Number.isFinite(x)||x<f.min||x>f.max||(f.step===1&&!Number.isInteger(x))||(f.step===.1&&Math.abs(x*10-Math.round(x*10))>1e-7))errors.push(f.id);}}
 if(!errors.length&&score.validate)errors.push(...score.validate(values));
 return [...new Set(errors)];
}
export function calculate(id,values){const score=scores.find(s=>s.id===id);if(!score)throw new Error('Escore desconhecido.');if(typeof score.safeCalculate==='function')return score.safeCalculate(values);if(score.externalCalculator)return {complete:false,external:true,errors:[],reason:score.externalCalculationReason,url:score.externalCalculator};if(score.calculationSuspended)return {complete:false,suspended:true,errors:[],reason:score.calculationSuspensionReason};const errors=validate(score,values);if(errors.length){const partial=score.assessPartial?.(values);return score.id==='raimondi'?{complete:false,total:null,errors}:{complete:false,errors,...(partial?{riskFloor:partial.riskFloor,level:partial.level,alerts:[partial.alert],reason:partial.alert}: {})};}
 const x=Object.fromEntries(score.fields.map(f=>[f.id,(score.id==='duke-treadmill'||score.id==='duke-alexander-1998'||score.id==='duke-mark-1991')?values[f.id]:values[f.id]==='NT'?'NT':score.id==='pim3'&&f.type==='number'&&['sbp','fio2','pao2','be'].includes(f.id)&&f.allowND===true&&values[f.id]==='ND'?'ND':Number(values[f.id])]));
 if(score.expanded)return calculateExpanded(score,x);
 let breakdown=score.fields.map(f=>({label:f.label,points:x[f.id]}));let total=breakdown.reduce((sum,r)=>sum+(typeof r.points==='number'?r.points:0),0);
 let label='',level='low',action='',audit='';
 if(id==='glasgow'&&Object.values(x).includes('NT'))return {complete:true,total:null,label:'Total não calculável',level:'medium',action:'Há componente não testável. Documente E, V e M; não transforme NT em 1 nem estime o total.',breakdown,audit:`E${x.eye} V${x.verbal} M${x.motor}`};
 if(id==='news2'){
 const rr=x.rr<=8?3:x.rr<=11?1:x.rr<=20?0:x.rr<=24?2:3;
 const sat=x.scale===1?(x.spo<=91?3:x.spo<=93?2:x.spo<=95?1:0):(x.spo<=83?3:x.spo<=85?2:x.spo<=87?1:x.spo<=92?0:x.oxygen===0?0:x.spo<=94?1:x.spo<=96?2:3);
 const bp=x.sbp<=90?3:x.sbp<=100?2:x.sbp<=110?1:x.sbp<220?0:3;
 const hr=x.hr<=40?3:x.hr<=50?1:x.hr<=90?0:x.hr<=110?1:x.hr<=130?2:3;
 const temp=x.temp<=35?3:x.temp<=36?1:x.temp<=38?0:x.temp<=39?1:2;
 breakdown=[{label:'FR',points:rr},{label:`SpO₂ · escala ${x.scale}`,points:sat},{label:'O₂',points:x.oxygen},{label:'PAS',points:bp},{label:'FC',points:hr},{label:'Consciência',points:x.mental},{label:'Temperatura',points:temp}];total=breakdown.reduce((s,r)=>s+r.points,0);
 if(total>=7){label='Alto risco · resposta emergencial';level='high';action='Avaliação imediata por equipe com competências de cuidados críticos e monitorização contínua.';}else if(total>=5){label='Risco intermediário · resposta urgente';level='medium';action='Avaliação clínica urgente e observações pelo menos horárias até definição do plano.';}else if(breakdown.some(b=>b.points===3)){label='Alerta por componente com 3 pontos';level='medium';action='Revisão clínica urgente e observações pelo menos horárias, mesmo com total <5.';}else{label=total===0?'Sem pontos no momento':'Menor risco agregado';action=total===0?'Manter vigilância clínica. NEWS2 zero não exclui doença grave.':'Reavaliar e definir frequência de observações conforme evolução.';}
 }else if(id==='pasi'){breakdown=[0.1,0.2,0.3,0.4].map((weight,i)=>({label:['Cabeça','Membros superiores','Tronco','Membros inferiores'][i],points:weight*x['area'+i]*(x['p'+i+0]+x['p'+i+1]+x['p'+i+2])}));total=breakdown.reduce((s,b)=>s+b.points,0);label='Índice de extensão e intensidade';action='Compare avaliações seriadas e integre sítios especiais e impacto na qualidade de vida. Não há indicação terapêutica automática.';audit='Σ peso × área × (eritema + espessura + descamação)';
 }else if(id==='scorad'){const B=[0,1,2,3,4,5].reduce((s,i)=>s+x['sign'+i],0);const C=x.itch+x.sleep;total=x.area/5+3.5*B+C;breakdown=[{label:'A/5 · área',points:x.area/5},{label:'7B/2 · intensidade',points:3.5*B},{label:'C · sintomas',points:C}];label='Índice de gravidade';action='Maior valor indica maior carga clínica. Compare com avaliações anteriores e examine sinais de complicação.';audit=`${x.area}/5 + 7×${B}/2 + ${C}`;
 }else if(id==='ecog'||id==='karnofsky'){label=id==='ecog'?`ECOG ${total}`:`Karnofsky ${total}%`;action=score.fields[0].options.find(o=>Number(o.value)===total).label;level=id==='ecog'?(total>=3?'high':total===2?'medium':'low'):(total<=40?'high':total<=60?'medium':'low');
 }else {const b=score.bands.find(b=>total<=b[0]);[,,level,action]=b;label=b[1];}
 total=Math.round((total+Number.EPSILON)*100)/100;
 audit=audit||breakdown.map(b=>b.points).join(' + ');
 if(id==='glasgow')audit=`E${x.eye} + V${x.verbal} + M${x.motor}`;
 const alerts=[];
 if(id==='westley-rcht-2023'&&x.stridor===2)alerts.push('Estridor em repouso exige avaliação imediata, mesmo com soma na faixa Leve; não definir alta pela pontuação.');
 if(['westley','westley-rcht-2023'].includes(id)&&(x.cyanosis>0||x.mental===5))alerts.push('Sinal crítico: cianose ou alteração de consciência exige avaliação imediata e suporte de via aérea, independentemente da faixa numérica.');
 if(id==='pram'&&x.air===3)alerts.push('Entrada de ar mínima ou ausente é sinal de alarme. Avalie ventilação, exaustão e necessidade de suporte imediato, independentemente do total.');
 return {complete:true,total,label,level,action,alerts,breakdown,audit:`${audit} = ${total}`};
}
